use std::io::{self, Read, Write};

struct Parser<'a> {
    s: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn skip_ws(&mut self) {
        while self.pos < self.s.len() && (self.s[self.pos] == b' ' || self.s[self.pos] == b'\t') {
            self.pos += 1;
        }
    }

    fn peek(&mut self) -> Option<u8> {
        self.skip_ws();
        self.s.get(self.pos).copied()
    }

    // expr := term (('+' | '-') term)*
    fn expr(&mut self) -> Option<i64> {
        let mut v = self.term()?;
        loop {
            match self.peek() {
                Some(b'+') => {
                    self.pos += 1;
                    let r = self.term()?;
                    v = v.wrapping_add(r);
                }
                Some(b'-') => {
                    self.pos += 1;
                    let r = self.term()?;
                    v = v.wrapping_sub(r);
                }
                _ => return Some(v),
            }
        }
    }

    // term := unary (('*' | '/' | '%') unary)*
    fn term(&mut self) -> Option<i64> {
        let mut v = self.unary()?;
        loop {
            match self.peek() {
                Some(b'*') => {
                    self.pos += 1;
                    let r = self.unary()?;
                    v = v.wrapping_mul(r);
                }
                Some(b'/') => {
                    self.pos += 1;
                    let r = self.unary()?;
                    if r == 0 {
                        return None;
                    }
                    v = v.wrapping_div(r);
                }
                Some(b'%') => {
                    self.pos += 1;
                    let r = self.unary()?;
                    if r == 0 {
                        return None;
                    }
                    v = v.wrapping_rem(r);
                }
                _ => return Some(v),
            }
        }
    }

    // unary := '-' unary | primary
    fn unary(&mut self) -> Option<i64> {
        if self.peek() == Some(b'-') {
            self.pos += 1;
            let v = self.unary()?;
            return Some(v.wrapping_neg());
        }
        self.primary()
    }

    // primary := number | '(' expr ')'
    fn primary(&mut self) -> Option<i64> {
        match self.peek()? {
            b'(' => {
                self.pos += 1;
                let v = self.expr()?;
                if self.peek() != Some(b')') {
                    return None;
                }
                self.pos += 1;
                Some(v)
            }
            b'0'..=b'9' => {
                let mut v: i64 = 0;
                while let Some(&c) = self.s.get(self.pos) {
                    if !c.is_ascii_digit() {
                        break;
                    }
                    v = v.wrapping_mul(10).wrapping_add((c - b'0') as i64);
                    self.pos += 1;
                }
                Some(v)
            }
            _ => None,
        }
    }
}

fn evaluate(line: &str) -> Option<i64> {
    let mut p = Parser {
        s: line.as_bytes(),
        pos: 0,
    };
    let v = p.expr()?;
    if p.peek().is_some() {
        return None;
    }
    Some(v)
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut out = String::new();
    for line in input.lines() {
        match evaluate(line) {
            Some(v) => out.push_str(&format!("{}\n", v)),
            None => out.push_str("error\n"),
        }
    }
    io::stdout().write_all(out.as_bytes()).unwrap();
}
